Ext._define('rh.cadastralquality.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.cadastralquality.Window',

    configOrderToolBar: ['add', 'edit', 'remove','reportAll', '-', 'search'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: '', dataIndex: 'icons', width: 30, renderer: core.rendererIconGrid},
                    //{header: 'Descrição', dataIndex: 'description', id: 'autoExpandColumn',hidden: true},
                    {header: 'Título', dataIndex: 'title', id: 'autoExpandColumn'},
                    //{header: 'Descrição', dataIndex: 'description', width: 300},
                    {header: 'Consulta Sql', dataIndex: 'sql', width: 90, hidden: true}
                ]
            );

        return this._columnModel;
    },

    getReportAllAction:function(){
        return{
            text: 'Relatório Completo',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/rh/images/relatorios.png',
            handler: function () {
               this._report()
            }
        }

    },

    _report: function (window_) {
        params = {}
        var rest = Ext._create("rh.cadastralquality.Restful", { resource: this.resource });
        var mask = Ext._create("Ext.LoadMask", this.getEl(), { msg: "Processando informações." });
        var _grid = this;
        var wnd = window_ == null ? this : window_;

        if (wnd.externalCallback == undefined)
            wnd.externalCallback = {
                fn: function (message) {
                    _grid.getStore().load();
                },
            };
        mask.show();
        rest._report(
            params,
            {
                scope: this,
                fn: function (rst) {
                    console.info(rst);
                    core.invokeCallback(wnd.externalCallback || { fn: Ext.emptyFn }, rst);
                },
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: "Informando",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message,
                    });
                },
            },
            {
                fn: function () {
                    mask.hide();
                },
            }
        );
    },

    defaultClickFunction: function() {
        if(this.getSelectionModel().getSelected()) this.OpenReportWindow();
    },

    OpenReportWindow:function(){
        params = this.getSelectionModel().getSelected()
        Ext._create('rh.cadastralquality.OpenReportWindow', {
            title: 'Relatório de Qualidade Cadastral',
            scope: this,
            pk: params.id,
            closable: true,
        }).show();
    },
});

core.RestfulGrid.register(
    'rh.cadastralquality.Restful',
    'rh.cadastralquality.Grid'
);

